import inspect

from timing import timed


@timed
def checkout(cart):
    """Charge the cart and return a receipt."""
    return f"receipt:{cart}"


def test_name_preserved():
    assert checkout.__name__ == "checkout", "use functools.wraps"


def test_docstring_preserved():
    assert checkout.__doc__ == "Charge the cart and return a receipt."


def test_signature_preserved():
    assert list(inspect.signature(checkout).parameters) == ["cart"]


def test_wrapped_present():
    assert hasattr(checkout, "__wrapped__")

import timing
from timing import timed


def test_return_value_unchanged():
    @timed
    def add(a, b):
        return a + b

    assert add(2, 3) == 5


def test_duration_is_recorded():
    @timed
    def work():
        return sum(range(1000))

    work()
    assert timing.last_duration_s >= 0.0
